import z3

solver = z3.Solver()

groups = [[z3.Int(f'g_{w}_{p}') for p in range(30)] for w in range(7)]

for w in range(7):
    for p in range(30):
        solver.add(groups[w][p] >= 0, groups[w][p] <= 9)

for w in range(7):
    for g in range(10):
        count = z3.Sum([z3.If(groups[w][p] == g, 1, 0) for p in range(30)])
        solver.add(count == 3)

for p1 in range(30):
    for p2 in range(p1+1, 30):
        together = z3.Sum([z3.If(groups[w][p1] == groups[w][p2], 1, 0) for w in range(7)])
        solver.add(together <= 1)

result = solver.check()
print(result)

if result == z3.sat:
    model = solver.model()
    solution = []
    for w in range(7):
        for p in range(30):
            val = model[groups[w][p]].as_long()
            solution.append(val)
    print(solution)
